(283,71,'_elementor_data','[{\"id\":\"f8d4c49\",\"elType\":\"e-flexbox\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-7cecf89\"]}},\"elements\":[{\"id\":\"d00eb2c\",\"elType\":\"widget\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-d00eb2c-6aff905\"]},\"title\":{\"$$type\":\"html-v3\",\"value\":{\"content\":{\"$$type\":\"string\",\"value\":\"-  About Us  -\"},\"children\":[]}},\"link\":{\"$$type\":\"link\",\"value\":{\"isTargetBlank\":null}}},\"elements\":[],\"widgetType\":\"e-heading\",\"styles\":{\"e-d00eb2c-6aff905\":{\"id\":\"e-d00eb2c-6aff905\",\"label\":\"local\",\"type\":\"class\",\"variants\":[{\"meta\":{\"breakpoint\":\"desktop\",\"state\":null},\"props\":{\"align-self\":{\"$$type\":\"string\",\"value\":\"center\"}},\"custom_css\":null}]}},\"interactions\":[],\"editor_settings\":[],\"version\":\"0.0\"},{\"id\":\"6f47a94\",\"elType\":\"widget\",\"settings\":{\"html\":\"<!DOCTYPE html>\\n<html lang=\\\"en\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\" \\/>\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\" \\/>\\n    <title>About Sampreshan \\u2014 Preserving Sanatana Dharma | Vasudhaiva Kutumbakam<\\/title>\\n    <meta name=\\\"description\\\" content=\\\"Sampreshan is a digital initiative by ShivBodh Trust dedicated to preserving, protecting, and promoting Sanatana Dharma through respectful community participation, petitions, and constructive dialogue.\\\" \\/>\\n    <meta name=\\\"robots\\\" content=\\\"index, follow\\\" \\/>\\n    <link rel=\\\"canonical\\\" href=\\\"https:\\/\\/sampreshan.org\\/about.html\\\" \\/>\\n\\n    <!-- Open Graph -->\\n    <meta property=\\\"og:title\\\" content=\\\"About Sampreshan \\u2014 Preserving Sanatana Dharma\\\" \\/>\\n    <meta property=\\\"og:description\\\" content=\\\"Sampreshan is a digital initiative by ShivBodh Trust dedicated to preserving, protecting, and promoting Sanatana Dharma through respectful community participation.\\\" \\/>\\n    <meta property=\\\"og:type\\\" content=\\\"website\\\" \\/>\\n    <meta property=\\\"og:url\\\" content=\\\"https:\\/\\/sampreshan.org\\/about.html\\\" \\/>\\n    <meta property=\\\"og:site_name\\\" content=\\\"Sampreshan\\\" \\/>\\n    <meta property=\\\"og:locale\\\" content=\\\"en_IN\\\" \\/>\\n\\n    <!-- Twitter Card -->\\n    <meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\n    <meta name=\\\"twitter:title\\\" content=\\\"About Sampreshan \\u2014 Preserving Sanatana Dharma\\\" \\/>\\n    <meta name=\\\"twitter:description\\\" content=\\\"Sampreshan is a digital initiative by ShivBodh Trust dedicated to preserving, protecting, and promoting Sanatana Dharma through respectful community participation.\\\" \\/>\\n\\n    <!-- JSON-LD Schema Markup -->\\n    <script type=\\\"application\\/ld+json\\\">\\n        {\\n            \\\"@context\\\": \\\"https:\\/\\/schema.org\\\",\\n            \\\"@type\\\": \\\"Organization\\\",\\n            \\\"name\\\": \\\"Sampreshan\\\",\\n            \\\"email\\\": \\\"sampreshan.tech@gmail.com\\\",\\n            \\\"parentOrganization\\\": {\\n                \\\"@type\\\": \\\"Organization\\\",\\n                \\\"name\\\": \\\"ShivBodh Trust\\\"\\n            },\\n            \\\"url\\\": \\\"https:\\/\\/sampreshan.org\\\",\\n            \\\"description\\\": \\\"Sampreshan is a digital initiative inspired by ShivBodh Trust, created to support the preservation, protection, and promotion of Sanatana Dharma through respectful community participation, petitions, discussions, awareness campaigns, and communication with Dharmacharyas, temples, religious organizations, and Hindu institutions.\\\",\\n            \\\"sameAs\\\": []\\n        }\\n    <\\/script>\\n    <script type=\\\"application\\/ld+json\\\">\\n        {\\n            \\\"@context\\\": \\\"https:\\/\\/schema.org\\\",\\n            \\\"@type\\\": \\\"AboutPage\\\",\\n            \\\"name\\\": \\\"About Sampreshan\\\",\\n            \\\"description\\\": \\\"Learn about Sampreshan \\u2014 a digital initiative by ShivBodh Trust for preserving Sanatana Dharma through community participation and respectful dialogue.\\\",\\n            \\\"url\\\": \\\"https:\\/\\/sampreshan.org\\/about.html\\\",\\n            \\\"isPartOf\\\": {\\n                \\\"@type\\\": \\\"WebSite\\\",\\n                \\\"name\\\": \\\"Sampreshan\\\",\\n                \\\"url\\\": \\\"https:\\/\\/sampreshan.org\\\"\\n            }\\n        }\\n    <\\/script>\\n    <script type=\\\"application\\/ld+json\\\">\\n        {\\n            \\\"@context\\\": \\\"https:\\/\\/schema.org\\\",\\n            \\\"@type\\\": \\\"WebSite\\\",\\n            \\\"name\\\": \\\"Sampreshan\\\",\\n            \\\"url\\\": \\\"https:\\/\\/sampreshan.org\\\",\\n            \\\"description\\\": \\\"Sampreshan is a digital initiative inspired by ShivBodh Trust, created to support the preservation, protection, and promotion of Sanatana Dharma through respectful community participation.\\\",\\n            \\\"potentialAction\\\": {\\n                \\\"@type\\\": \\\"SearchAction\\\",\\n                \\\"target\\\": \\\"https:\\/\\/sampreshan.org\\/search?q={search_term_string}\\\",\\n                \\\"query-input\\\": \\\"required name=search_term_string\\\"\\n            }\\n        }\\n    <\\/script>\\n\\n    <style>\\n        \\/* ===== CSS Reset & Base ===== *\\/\\n        *,\\n        *::before,\\n        *::after {\\n            margin: 0;\\n            padding: 0;\\n            box-sizing: border-box;\\n        }\\n\\n        :root {\\n            --saffron: #FF9933;\\n            --saffron-dark: #e0851a;\\n            --saffron-light: #ffe4b3;\\n            --deep-blue: #1E3A8A;\\n            --deep-blue-dark: #152b66;\\n            --deep-blue-light: #2a4bb5;\\n            --white: #FFFFFF;\\n            --off-white: #f8f6f0;\\n            --light-bg: #f5f2eb;\\n            --gray-light: #e8e4da;\\n            --gray-mid: #8a867a;\\n            --text-dark: #1a1a1a;\\n            --text-muted: #4a473f;\\n            --shadow-sm: 0 2px 12px rgba(30, 58, 138, 0.08);\\n            --shadow-md: 0 8px 32px rgba(30, 58, 138, 0.12);\\n            --shadow-lg: 0 16px 48px rgba(30, 58, 138, 0.16);\\n            --radius: 12px;\\n            --radius-lg: 20px;\\n            --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);\\n            --font-sans: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', sans-serif;\\n        }\\n\\n        html {\\n            scroll-behavior: smooth;\\n            -webkit-font-smoothing: antialiased;\\n            -moz-osx-font-smoothing: grayscale;\\n        }\\n\\n        body {\\n            font-family: var(--font-sans);\\n            background-color: var(--white);\\n            color: var(--text-dark);\\n            line-height: 1.7;\\n            overflow-x: hidden;\\n        }\\n\\n        \\/* ===== Skip Link (a11y) ===== *\\/\\n        .skip-link {\\n            position: absolute;\\n            top: -100%;\\n            left: 1rem;\\n            padding: 0.75rem 1.5rem;\\n            background: var(--deep-blue);\\n            color: var(--white);\\n            border-radius: 0 0 var(--radius) var(--radius);\\n            z-index: 10000;\\n            font-weight: 600;\\n            text-decoration: none;\\n            transition: top 0.25s ease;\\n        }\\n        .skip-link:focus {\\n            top: 0;\\n        }\\n\\n        \\/* ===== Container ===== *\\/\\n        .container {\\n            max-width: 1200px;\\n            margin: 0 auto;\\n            padding: 0 1.25rem;\\n        }\\n\\n        \\/* ===== Buttons ===== *\\/\\n        .btn {\\n            display: inline-block;\\n            padding: 0.85rem 2.2rem;\\n            border: none;\\n            border-radius: 50px;\\n            font-size: 1rem;\\n            font-weight: 600;\\n            text-decoration: none;\\n            text-align: center;\\n            cursor: pointer;\\n            transition: var(--transition);\\n            font-family: inherit;\\n            line-height: 1.4;\\n        }\\n\\n        .btn-primary {\\n            background: var(--saffron);\\n            color: var(--white);\\n            box-shadow: 0 4px 16px rgba(255, 153, 51, 0.35);\\n        }\\n        .btn-primary:hover,\\n        .btn-primary:focus {\\n            background: var(--saffron-dark);\\n            transform: translateY(-2px);\\n            box-shadow: 0 8px 28px rgba(255, 153, 51, 0.45);\\n        }\\n        .btn-primary:focus-visible {\\n            outline: 3px solid var(--deep-blue);\\n            outline-offset: 2px;\\n        }\\n\\n        .btn-outline {\\n            background: transparent;\\n            color: var(--deep-blue);\\n            border: 2px solid var(--deep-blue);\\n        }\\n        .btn-outline:hover,\\n        .btn-outline:focus {\\n            background: var(--deep-blue);\\n            color: var(--white);\\n            transform: translateY(-2px);\\n            box-shadow: 0 8px 28px rgba(30, 58, 138, 0.25);\\n        }\\n        .btn-outline:focus-visible {\\n            outline: 3px solid var(--saffron);\\n            outline-offset: 2px;\\n        }\\n\\n        .btn-white {\\n            background: var(--white);\\n            color: var(--deep-blue);\\n            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.10);\\n        }\\n        .btn-white:hover,\\n        .btn-white:focus {\\n            background: var(--off-white);\\n            transform: translateY(-2px);\\n            box-shadow: 0 8px 28px rgba(0, 0, 0, 0.16);\\n        }\\n        .btn-white:focus-visible {\\n            outline: 3px solid var(--saffron);\\n            outline-offset: 2px;\\n        }\\n\\n        \\/* ===== Header \\/ Nav ===== *\\/\\n        .site-header {\\n            background: var(--white);\\n            border-bottom: 2px solid var(--gray-light);\\n            padding: 0.9rem 0;\\n            position: sticky;\\n            top: 0;\\n            z-index: 1000;\\n            backdrop-filter: blur(8px);\\n            background: rgba(255, 255, 255, 0.92);\\n        }\\n\\n        .header-inner {\\n            display: flex;\\n            align-items: center;\\n            justify-content: space-between;\\n            flex-wrap: wrap;\\n            gap: 0.75rem 1.5rem;\\n        }\\n\\n        .logo {\\n            display: flex;\\n            align-items: center;\\n            gap: 0.5rem;\\n            text-decoration: none;\\n            color: var(--deep-blue);\\n        }\\n        .logo-icon {\\n            display: flex;\\n            align-items: center;\\n            justify-content: center;\\n            width: 44px;\\n            height: 44px;\\n            background: var(--saffron);\\n            border-radius: 50%;\\n            color: var(--white);\\n            font-size: 1.5rem;\\n            font-weight: 700;\\n            flex-shrink: 0;\\n        }\\n        .logo-text {\\n            font-size: 1.3rem;\\n            font-weight: 700;\\n            letter-spacing: -0.02em;\\n        }\\n        .logo-text span {\\n            color: var(--saffron);\\n        }\\n        .logo-tagline {\\n            display: block;\\n            font-size: 0.7rem;\\n            font-weight: 400;\\n            color: var(--gray-mid);\\n            letter-spacing: 0.06em;\\n            text-transform: uppercase;\\n        }\\n\\n        .nav-links {\\n            display: flex;\\n            align-items: center;\\n            gap: 1.75rem;\\n            list-style: none;\\n        }\\n        .nav-links a {\\n            text-decoration: none;\\n            color: var(--text-dark);\\n            font-weight: 500;\\n            font-size: 0.95rem;\\n            transition: var(--transition);\\n            position: relative;\\n        }\\n        .nav-links a::after {\\n            content: \'\';\\n            position: absolute;\\n            bottom: -4px;\\n            left: 0;\\n            width: 0;\\n            height: 2px;\\n            background: var(--saffron);\\n            transition: var(--transition);\\n        }\\n        .nav-links a:hover::after,\\n        .nav-links a:focus::after {\\n            width: 100%;\\n        }\\n        .nav-links a:focus-visible {\\n            outline: 2px solid var(--saffron);\\n            outline-offset: 4px;\\n            border-radius: 4px;\\n        }\\n        .nav-links .active {\\n            color: var(--saffron-dark);\\n            font-weight: 600;\\n        }\\n        .nav-links .active::after {\\n            width: 100%;\\n        }\\n\\n        .nav-toggle {\\n            display: none;\\n            flex-direction: column;\\n            gap: 5px;\\n            background: none;\\n            border: none;\\n            cursor: pointer;\\n            padding: 6px 4px;\\n            border-radius: 6px;\\n        }\\n        .nav-toggle span {\\n            display: block;\\n            width: 28px;\\n            height: 3px;\\n            background: var(--deep-blue);\\n            border-radius: 4px;\\n            transition: var(--transition);\\n            transform-origin: center;\\n        }\\n        .nav-toggle[aria-expanded=\\\"true\\\"] span:nth-child(1) {\\n            transform: rotate(45deg) translate(5px, 6px);\\n        }\\n        .nav-toggle[aria-expanded=\\\"true\\\"] span:nth-child(2) {\\n            opacity: 0;\\n        }\\n        .nav-toggle[aria-expanded=\\\"true\\\"] span:nth-child(3) {\\n            transform: rotate(-45deg) translate(5px, -6px);\\n        }\\n        .nav-toggle:focus-visible {\\n            outline: 2px solid var(--saffron);\\n            outline-offset: 2px;\\n        }\\n\\n        \\/* ===== Hero ===== *\\/\\n        .hero {\\n            background: linear-gradient(145deg, var(--deep-blue) 0%, #0f2a5c 100%);\\n            color: var(--white);\\n            padding: 5rem 0 4.5rem;\\n            position: relative;\\n            overflow: hidden;\\n        }\\n        .hero::before {\\n            content: \'\\u0950\';\\n            position: absolute;\\n            right: -2rem;\\n            top: -2rem;\\n            font-size: 22rem;\\n            opacity: 0.035;\\n            pointer-events: none;\\n            line-height: 1;\\n            font-weight: 700;\\n            color: var(--white);\\n        }\\n        .hero::after {\\n            content: \'\';\\n            position: absolute;\\n            bottom: 0;\\n            left: 0;\\n            right: 0;\\n            height: 6px;\\n            background: var(--saffron);\\n        }\\n        .hero-content {\\n            position: relative;\\n            z-index: 2;\\n            max-width: 780px;\\n        }\\n        .hero-badge {\\n            display: inline-block;\\n            background: rgba(255, 153, 51, 0.20);\\n            color: var(--saffron-light);\\n            padding: 0.3rem 1.2rem;\\n            border-radius: 50px;\\n            font-size: 0.8rem;\\n            font-weight: 600;\\n            letter-spacing: 0.06em;\\n            text-transform: uppercase;\\n            margin-bottom: 1.2rem;\\n            border: 1px solid rgba(255, 153, 51, 0.25);\\n        }\\n        .hero h1 {\\n            font-size: clamp(2.6rem, 8vw, 4.2rem);\\n            font-weight: 800;\\n            line-height: 1.1;\\n            letter-spacing: -0.02em;\\n            margin-bottom: 0.5rem;\\n        }\\n        .hero h1 .highlight {\\n            color: var(--saffron);\\n        }\\n        .hero .tagline {\\n            font-size: clamp(1rem, 2vw, 1.3rem);\\n            font-weight: 400;\\n            color: rgba(255, 255, 255, 0.75);\\n            margin-bottom: 1.5rem;\\n            font-style: italic;\\n            letter-spacing: 0.04em;\\n        }\\n        .hero p {\\n            font-size: 1.1rem;\\n            color: rgba(255, 255, 255, 0.85);\\n            max-width: 620px;\\n            margin-bottom: 2rem;\\n            line-height: 1.8;\\n        }\\n        .hero-actions {\\n            display: flex;\\n            flex-wrap: wrap;\\n            gap: 1rem;\\n            align-items: center;\\n        }\\n\\n        \\/* ===== Section Shared ===== *\\/\\n        section {\\n            padding: 4.5rem 0;\\n        }\\n        .section-title {\\n            font-size: clamp(2rem, 5vw, 2.8rem);\\n            font-weight: 700;\\n            color: var(--deep-blue);\\n            margin-bottom: 0.75rem;\\n            letter-spacing: -0.02em;\\n            line-height: 1.2;\\n        }\\n        .section-title .highlight {\\n            color: var(--saffron);\\n        }\\n        .section-subtitle {\\n            font-size: 1.1rem;\\n            color: var(--text-muted);\\n            max-width: 700px;\\n            margin-bottom: 2.5rem;\\n            line-height: 1.8;\\n        }\\n        .section-subtitle.centered {\\n            margin-left: auto;\\n            margin-right: auto;\\n            text-align: center;\\n        }\\n        .text-center {\\n            text-align: center;\\n        }\\n\\n        .bg-light {\\n            background: var(--light-bg);\\n        }\\n        .bg-offwhite {\\n            background: var(--off-white);\\n        }\\n        .bg-white {\\n            background: var(--white);\\n        }\\n\\n        \\/* ===== What is Sampreshan ===== *\\/\\n        .what-is-grid {\\n            display: grid;\\n            grid-template-columns: 1fr 1fr;\\n            gap: 3rem;\\n            align-items: center;\\n        }\\n        .what-is-text p {\\n            font-size: 1.05rem;\\n            color: var(--text-muted);\\n            margin-bottom: 1.2rem;\\n            line-height: 1.8;\\n        }\\n        .what-is-text p:last-child {\\n            margin-bottom: 0;\\n        }\\n        .what-is-visual {\\n            display: flex;\\n            justify-content: center;\\n            align-items: center;\\n        }\\n        .what-is-visual .visual-box {\\n            background: var(--deep-blue);\\n            color: var(--white);\\n            padding: 2.5rem 2rem;\\n            border-radius: var(--radius-lg);\\n            text-align: center;\\n            width: 100%;\\n            max-width: 380px;\\n            box-shadow: var(--shadow-lg);\\n            position: relative;\\n            overflow: hidden;\\n        }\\n        .visual-box .logo-image {\\n            max-width: 80%;\\n            height: auto;\\n            margin-bottom: 0.75rem;\\n            display: block;\\n            margin-left: auto;\\n            margin-right: auto;\\n            filter: brightness(0) invert(1); \\/* make white to match theme *\\/\\n        }\\n        \\/* For better visibility, we can use a white logo; if the SVG has dark colors, we might want to keep original, but we\'ll add a class to handle *\\/\\n        .visual-box h3 {\\n            font-size: 1.5rem;\\n            font-weight: 700;\\n            margin-bottom: 0.3rem;\\n        }\\n        .visual-box p {\\n            color: rgba(255, 255, 255, 0.8);\\n            font-size: 0.95rem;\\n        }\\n        .visual-box .om-bg {\\n            position: absolute;\\n            right: -10px;\\n            bottom: -20px;\\n            font-size: 8rem;\\n            opacity: 0.06;\\n            pointer-events: none;\\n            font-weight: 700;\\n        }\\n\\n        \\/* ===== Mission ===== *\\/\\n        .mission-grid {\\n            display: grid;\\n            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\\n            gap: 1.75rem;\\n            margin-top: 1rem;\\n        }\\n        .mission-card {\\n            background: var(--white);\\n            padding: 2rem 1.5rem;\\n            border-radius: var(--radius);\\n            box-shadow: var(--shadow-sm);\\n            transition: var(--transition);\\n            border-top: 4px solid var(--saffron);\\n            text-align: center;\\n        }\\n        .mission-card:hover {\\n            transform: translateY(-6px);\\n            box-shadow: var(--shadow-md);\\n        }\\n        .mission-card .icon {\\n            font-size: 2.4rem;\\n            display: block;\\n            margin-bottom: 0.75rem;\\n        }\\n        .mission-card h3 {\\n            font-size: 1.1rem;\\n            font-weight: 700;\\n            color: var(--deep-blue);\\n            margin-bottom: 0.4rem;\\n        }\\n        .mission-card p {\\n            font-size: 0.95rem;\\n            color: var(--text-muted);\\n            line-height: 1.6;\\n        }\\n\\n        \\/* ===== How It Works ===== *\\/\\n        .steps-grid {\\n            display: grid;\\n            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\\n            gap: 2rem;\\n            margin-top: 1rem;\\n        }\\n        .step-card {\\n            background: var(--white);\\n            padding: 2rem 1.5rem;\\n            border-radius: var(--radius);\\n            box-shadow: var(--shadow-sm);\\n            transition: var(--transition);\\n            text-align: center;\\n            position: relative;\\n            border: 1px solid var(--gray-light);\\n        }\\n        .step-card:hover {\\n            transform: translateY(-6px);\\n            box-shadow: var(--shadow-md);\\n            border-color: var(--saffron);\\n        }\\n        .step-number {\\n            display: inline-flex;\\n            align-items: center;\\n            justify-content: center;\\n            width: 48px;\\n            height: 48px;\\n            background: var(--deep-blue);\\n            color: var(--white);\\n            font-size: 1.2rem;\\n            font-weight: 700;\\n            border-radius: 50%;\\n            margin-bottom: 1rem;\\n        }\\n        .step-card h3 {\\n            font-size: 1.1rem;\\n            font-weight: 700;\\n            color: var(--deep-blue);\\n            margin-bottom: 0.4rem;\\n        }\\n        .step-card p {\\n            font-size: 0.95rem;\\n            color: var(--text-muted);\\n            line-height: 1.6;\\n            margin: 0;\\n        }\\n\\n        \\/* ===== Principles ===== *\\/\\n        .principles-grid {\\n            display: grid;\\n            grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\\n            gap: 1.5rem;\\n            margin-top: 1rem;\\n        }\\n        .principle-card {\\n            background: var(--white);\\n            padding: 1.75rem 1.25rem;\\n            border-radius: var(--radius);\\n            box-shadow: var(--shadow-sm);\\n            text-align: center;\\n            transition: var(--transition);\\n            border-bottom: 3px solid transparent;\\n        }\\n        .principle-card:hover {\\n            border-bottom-color: var(--saffron);\\n            transform: translateY(-4px);\\n            box-shadow: var(--shadow-md);\\n        }\\n        .principle-card .icon {\\n            font-size: 2rem;\\n            display: block;\\n            margin-bottom: 0.5rem;\\n        }\\n        .principle-card h4 {\\n            font-size: 1rem;\\n            font-weight: 700;\\n            color: var(--deep-blue);\\n            margin-bottom: 0.2rem;\\n        }\\n        .principle-card p {\\n            font-size: 0.85rem;\\n            color: var(--text-muted);\\n            line-height: 1.5;\\n            margin: 0;\\n        }\\n\\n        \\/* ===== Allowed \\/ Not Allowed ===== *\\/\\n        .two-col-grid {\\n            display: grid;\\n            grid-template-columns: 1fr 1fr;\\n            gap: 2.5rem;\\n            margin-top: 1rem;\\n        }\\n        .list-card {\\n            background: var(--white);\\n            padding: 2rem 2rem 2rem 2.5rem;\\n            border-radius: var(--radius);\\n            box-shadow: var(--shadow-sm);\\n            border-left: 5px solid var(--saffron);\\n        }\\n        .list-card h3 {\\n            font-size: 1.3rem;\\n            font-weight: 700;\\n            color: var(--deep-blue);\\n            margin-bottom: 1rem;\\n            display: flex;\\n            align-items: center;\\n            gap: 0.6rem;\\n        }\\n        .list-card ul {\\n            list-style: none;\\n            padding: 0;\\n            margin: 0;\\n        }\\n        .list-card ul li {\\n            padding: 0.4rem 0;\\n            font-size: 1rem;\\n            color: var(--text-muted);\\n            display: flex;\\n            align-items: flex-start;\\n            gap: 0.6rem;\\n            border-bottom: 1px solid var(--gray-light);\\n        }\\n        .list-card ul li:last-child {\\n            border-bottom: none;\\n        }\\n        .list-card ul li .check {\\n            color: #2b8a3e;\\n            font-weight: 700;\\n            flex-shrink: 0;\\n        }\\n        .list-card ul li .cross {\\n            color: #c0392b;\\n            font-weight: 700;\\n            flex-shrink: 0;\\n        }\\n        .list-card.not-allowed {\\n            border-left-color: #c0392b;\\n        }\\n\\n        \\/* ===== ShivBodh Trust ===== *\\/\\n        .trust-card {\\n            background: var(--white);\\n            padding: 2.5rem 3rem;\\n            border-radius: var(--radius-lg);\\n            box-shadow: var(--shadow-sm);\\n            max-width: 900px;\\n            margin: 0 auto;\\n            border: 1px solid var(--gray-light);\\n            display: flex;\\n            gap: 2rem;\\n            align-items: center;\\n            flex-wrap: wrap;\\n        }\\n        .trust-card .trust-icon {\\n            font-size: 3.6rem;\\n            flex-shrink: 0;\\n        }\\n        .trust-card .trust-text h3 {\\n            font-size: 1.4rem;\\n            font-weight: 700;\\n            color: var(--deep-blue);\\n            margin-bottom: 0.3rem;\\n        }\\n        .trust-card .trust-text p {\\n            font-size: 1rem;\\n            color: var(--text-muted);\\n            line-height: 1.8;\\n            margin: 0;\\n        }\\n\\n        \\/* ===== Contact ===== *\\/\\n        .contact-box {\\n            background: var(--deep-blue);\\n            color: var(--white);\\n            padding: 3rem 2.5rem;\\n            border-radius: var(--radius-lg);\\n            box-shadow: var(--shadow-lg);\\n            max-width: 780px;\\n            margin: 0 auto;\\n            text-align: center;\\n        }\\n        .contact-box h2 {\\n            font-size: 2rem;\\n            font-weight: 700;\\n            margin-bottom: 0.5rem;\\n            color: var(--white);\\n        }\\n        .contact-box p {\\n            color: rgba(255, 255, 255, 0.8);\\n            font-size: 1.05rem;\\n            margin-bottom: 1.5rem;\\n        }\\n        .contact-box .email-link {\\n            display: inline-flex;\\n            align-items: center;\\n            gap: 0.6rem;\\n            background: var(--saffron);\\n            color: var(--white);\\n            padding: 0.85rem 2.2rem;\\n            border-radius: 50px;\\n            text-decoration: none;\\n            font-weight: 600;\\n            font-size: 1.05rem;\\n            transition: var(--transition);\\n            box-shadow: 0 4px 16px rgba(255, 153, 51, 0.3);\\n        }\\n        .contact-box .email-link:hover,\\n        .contact-box .email-link:focus {\\n            background: var(--saffron-dark);\\n            transform: translateY(-2px);\\n            box-shadow: 0 8px 28px rgba(255, 153, 51, 0.45);\\n        }\\n        .contact-box .email-link:focus-visible {\\n            outline: 3px solid var(--white);\\n            outline-offset: 2px;\\n        }\\n\\n        \\/* ===== Footer ===== *\\/\\n        .site-footer {\\n            background: var(--deep-blue-dark);\\n            color: rgba(255, 255, 255, 0.8);\\n            padding: 2.5rem 0 2rem;\\n            border-top: 4px solid var(--saffron);\\n        }\\n        .footer-inner {\\n            display: flex;\\n            flex-wrap: wrap;\\n            justify-content: space-between;\\n            align-items: center;\\n            gap: 1rem 2rem;\\n        }\\n        .footer-brand .footer-logo {\\n            font-size: 1.3rem;\\n            font-weight: 700;\\n            color: var(--white);\\n        }\\n        .footer-brand .footer-logo span {\\n            color: var(--saffron);\\n        }\\n        .footer-brand .footer-tagline {\\n            font-size: 0.85rem;\\n            color: rgba(255, 255, 255, 0.55);\\n            font-style: italic;\\n            letter-spacing: 0.04em;\\n        }\\n        .footer-copy {\\n            font-size: 0.9rem;\\n            color: rgba(255, 255, 255, 0.6);\\n            text-align: right;\\n        }\\n        .footer-copy .year {\\n            font-weight: 600;\\n        }\\n\\n        \\/* ===== Animations ===== *\\/\\n        @keyframes fadeInUp {\\n            from {\\n                opacity: 0;\\n                transform: translateY(30px);\\n            }\\n            to {\\n                opacity: 1;\\n                transform: translateY(0);\\n            }\\n        }\\n        .animate-on-view {\\n            opacity: 0;\\n            transform: translateY(30px);\\n            transition: opacity 0.7s ease, transform 0.7s ease;\\n        }\\n        .animate-on-view.visible {\\n            opacity: 1;\\n            transform: translateY(0);\\n        }\\n\\n        \\/* ===== Responsive ===== *\\/\\n        @media (max-width: 992px) {\\n            .what-is-grid {\\n                grid-template-columns: 1fr;\\n                gap: 2rem;\\n            }\\n            .what-is-visual .visual-box {\\n                max-width: 100%;\\n            }\\n            .two-col-grid {\\n                grid-template-columns: 1fr;\\n                gap: 1.5rem;\\n            }\\n        }\\n\\n        @media (max-width: 768px) {\\n            section {\\n                padding: 3rem 0;\\n            }\\n            .hero {\\n                padding: 3.5rem 0 3rem;\\n            }\\n            .hero h1 {\\n                font-size: clamp(2rem, 7vw, 2.8rem);\\n            }\\n\\n            .nav-toggle {\\n                display: flex;\\n            }\\n            .nav-links {\\n                display: none;\\n                flex-direction: column;\\n                width: 100%;\\n                padding: 1rem 0 0.5rem;\\n                gap: 0.75rem;\\n                border-top: 1px solid var(--gray-light);\\n                margin-top: 0.5rem;\\n            }\\n            .nav-links.open {\\n                display: flex;\\n            }\\n            .header-inner {\\n                flex-wrap: wrap;\\n            }\\n\\n            .trust-card {\\n                padding: 1.75rem;\\n                flex-direction: column;\\n                text-align: center;\\n            }\\n            .contact-box {\\n                padding: 2rem 1.5rem;\\n            }\\n            .contact-box h2 {\\n                font-size: 1.6rem;\\n            }\\n\\n            .footer-inner {\\n                flex-direction: column;\\n                text-align: center;\\n            }\\n            .footer-copy {\\n                text-align: center;\\n            }\\n\\n            .mission-grid {\\n                grid-template-columns: 1fr 1fr;\\n            }\\n            .steps-grid {\\n                grid-template-columns: 1fr 1fr;\\n            }\\n            .principles-grid {\\n                grid-template-columns: 1fr 1fr;\\n            }\\n        }\\n\\n        @media (max-width: 480px) {\\n            .container {\\n                padding: 0 1rem;\\n            }\\n            .hero p {\\n                font-size: 1rem;\\n            }\\n            .hero-actions .btn {\\n                width: 100%;\\n                justify-content: center;\\n            }\\n            .mission-grid {\\n                grid-template-columns: 1fr;\\n            }\\n            .steps-grid {\\n                grid-template-columns: 1fr;\\n            }\\n            .principles-grid {\\n                grid-template-columns: 1fr 1fr;\\n            }\\n            .list-card {\\n                padding: 1.5rem;\\n            }\\n            .logo-text {\\n                font-size: 1.1rem;\\n            }\\n            .logo-icon {\\n                width: 38px;\\n                height: 38px;\\n                font-size: 1.2rem;\\n            }\\n        }\\n    <\\/style>\\n<\\/head>\\n<body>\\n\\n    <!-- ===== Skip Link ===== -->\\n    <a class=\\\"skip-link\\\" href=\\\"#main-content\\\">Skip to main content<\\/a>\\n\\n    <!-- ===== Header ===== -->\\n    <header class=\\\"site-header\\\" role=\\\"banner\\\" aria-label=\\\"Site header\\\">\\n        <div class=\\\"container header-inner\\\">\\n            <a href=\\\"\\/\\\" class=\\\"logo\\\" aria-label=\\\"Sampreshan \\u2014 Home\\\">\\n                <span class=\\\"logo-icon\\\" aria-hidden=\\\"true\\\">\\u0938\\u0902<\\/span>\\n                <span class=\\\"logo-text\\\">Sampreshan<span>.<\\/span>\\n                    <span class=\\\"logo-tagline\\\">Vasudhaiva Kutumbakam<\\/span>\\n                <\\/span>\\n            <\\/a>\\n\\n            <button class=\\\"nav-toggle\\\" id=\\\"navToggle\\\" aria-expanded=\\\"false\\\" aria-controls=\\\"navLinks\\\" aria-label=\\\"Toggle navigation menu\\\">\\n                <span><\\/span>\\n                <span><\\/span>\\n                <span><\\/span>\\n            <\\/button>\\n\\n            <ul class=\\\"nav-links\\\" id=\\\"navLinks\\\" role=\\\"navigation\\\" aria-label=\\\"Main navigation\\\">\\n                <li><a href=\\\"\\/\\\">Home<\\/a><\\/li>\\n                <li><a href=\\\"\\/about.html\\\" class=\\\"active\\\" aria-current=\\\"page\\\">About<\\/a><\\/li>\\n                <li><a href=\\\"\\/petitions.html\\\">Petitions<\\/a><\\/li>\\n                <li><a href=\\\"\\/contact.html\\\">Contact<\\/a><\\/li>\\n            <\\/ul>\\n        <\\/div>\\n    <\\/header>\\n\\n    <!-- ===== Main ===== -->\\n    <main id=\\\"main-content\\\">\\n\\n        <!-- ===== Hero ===== -->\\n        <section class=\\\"hero\\\" aria-labelledby=\\\"hero-heading\\\">\\n            <div class=\\\"container hero-content\\\">\\n                <span class=\\\"hero-badge\\\">Digital Initiative<\\/span>\\n                <h1 id=\\\"hero-heading\\\">About <span class=\\\"highlight\\\">Sampreshan<\\/span><\\/h1>\\n                <p class=\\\"tagline\\\">\\\"Vasudhaiva Kutumbakam\\\" \\u2014 The world is one family<\\/p>\\n                <p>\\n                    Sampreshan is a digital initiative inspired by ShivBodh Trust, created to support\\n                    the preservation, protection, and promotion of Sanatana Dharma through respectful\\n                    community participation, petitions, discussions, awareness campaigns, and\\n                    communication with Dharmacharyas, temples, religious organizations, and Hindu\\n                    institutions.\\n                <\\/p>\\n                <div class=\\\"hero-actions\\\">\\n                    <a href=\\\"\\/petitions.html\\\" class=\\\"btn btn-primary\\\">Explore Petitions<\\/a>\\n                    <a href=\\\"#mission\\\" class=\\\"btn btn-outline btn-white\\\">Learn More<\\/a>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n        <!-- ===== What is Sampreshan ===== -->\\n        <section class=\\\"bg-light\\\" aria-labelledby=\\\"what-heading\\\" id=\\\"what\\\">\\n            <div class=\\\"container\\\">\\n                <div class=\\\"what-is-grid\\\">\\n                    <div class=\\\"what-is-text animate-on-view\\\">\\n                        <span class=\\\"hero-badge\\\" style=\\\"background:var(--saffron-light);color:var(--deep-blue);border-color:var(--saffron);\\\">About the Platform<\\/span>\\n                        <h2 id=\\\"what-heading\\\" class=\\\"section-title\\\">What is <span class=\\\"highlight\\\">Sampreshan<\\/span>?<\\/h2>\\n                        <p>\\n                            Sampreshan is a sacred digital platform that empowers devotees to raise\\n                            Dharma-related concerns, gather community support, and communicate\\n                            respectfully with relevant institutions. We believe in the power of\\n                            collective, thoughtful action rooted in the eternal values of Sanatana Dharma.\\n                        <\\/p>\\n                        <p>\\n                            Our platform enables every voice to be heard \\u2014 whether it is about\\n                            temple preservation, cultural heritage, or seeking guidance from\\n                            Dharmacharyas. We facilitate constructive dialogue, awareness campaigns,\\n                            and community-driven initiatives that uphold our rich spiritual legacy.\\n                        <\\/p>\\n                        <p>\\n                            Inspired by the vision of ShivBodh Trust, Sampreshan serves as a bridge\\n                            between the faithful and the institutions that guide and protect our\\n                            Dharma.\\n                        <\\/p>\\n                    <\\/div>\\n                    <div class=\\\"what-is-visual animate-on-view\\\">\\n                        <div class=\\\"visual-box\\\">\\n                            <!-- Added logo image -->\\n                            <img src=\\\"https:\\/\\/sampreshan.tech\\/wp-content\\/uploads\\/2026\\/06\\/sampreshan-logo-svg.svg\\\"\\n                                 alt=\\\"Sampreshan Logo - Dharma Seva\\\"\\n                                 class=\\\"logo-image\\\"\\n                                 width=\\\"200\\\" height=\\\"auto\\\" \\/>\\n                            <h3>Dharma Seva<\\/h3>\\n                            <p>Preserving, protecting &amp; promoting Sanatana Dharma<\\/p>\\n                            <span class=\\\"om-bg\\\" aria-hidden=\\\"true\\\">\\u0950<\\/span>\\n                        <\\/div>\\n                    <\\/div>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n        <!-- ===== Mission ===== -->\\n        <section id=\\\"mission\\\" aria-labelledby=\\\"mission-heading\\\">\\n            <div class=\\\"container\\\">\\n                <div class=\\\"text-center animate-on-view\\\">\\n                    <span class=\\\"hero-badge\\\" style=\\\"background:var(--saffron-light);color:var(--deep-blue);border-color:var(--saffron);display:inline-block;\\\">Our Purpose<\\/span>\\n                    <h2 id=\\\"mission-heading\\\" class=\\\"section-title\\\">Our <span class=\\\"highlight\\\">Mission<\\/span><\\/h2>\\n                    <p class=\\\"section-subtitle centered\\\">\\n                        Rooted in the eternal wisdom of Sanatana Dharma, our mission is to serve,\\n                        protect, and uplift through community participation and respectful dialogue.\\n                    <\\/p>\\n                <\\/div>\\n                <div class=\\\"mission-grid\\\">\\n                    <div class=\\\"mission-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\uded5<\\/span>\\n                        <h3>Preserve Sanatana Dharma<\\/h3>\\n                        <p>Safeguard the timeless traditions, scriptures, and practices that form the bedrock of Hindu civilization.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"mission-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83c\\udfdb\\ufe0f<\\/span>\\n                        <h3>Protect Cultural Heritage<\\/h3>\\n                        <p>Defend temples, monuments, and intangible heritage that embody the spiritual and artistic genius of Bharat.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"mission-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\udde3\\ufe0f<\\/span>\\n                        <h3>Encourage Constructive Dialogue<\\/h3>\\n                        <p>Foster respectful conversations among devotees, scholars, and institutions to address concerns with clarity and unity.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"mission-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\udcd6<\\/span>\\n                        <h3>Promote Awareness &amp; Education<\\/h3>\\n                        <p>Spread knowledge about Dharma, its principles, and its relevance in the modern world through campaigns and resources.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"mission-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83e\\udd1d<\\/span>\\n                        <h3>Support Community Welfare<\\/h3>\\n                        <p>Initiate and support projects that uplift communities, protect the environment, and serve society in the spirit of seva.<\\/p>\\n                    <\\/div>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n        <!-- ===== How It Works ===== -->\\n        <section class=\\\"bg-light\\\" aria-labelledby=\\\"how-heading\\\">\\n            <div class=\\\"container\\\">\\n                <div class=\\\"text-center animate-on-view\\\">\\n                    <span class=\\\"hero-badge\\\" style=\\\"background:var(--saffron-light);color:var(--deep-blue);border-color:var(--saffron);display:inline-block;\\\">Process<\\/span>\\n                    <h2 id=\\\"how-heading\\\" class=\\\"section-title\\\">How <span class=\\\"highlight\\\">Sampreshan<\\/span> Works<\\/h2>\\n                    <p class=\\\"section-subtitle centered\\\">\\n                        A simple four-step journey from raising a concern to reaching the right authorities.\\n                    <\\/p>\\n                <\\/div>\\n                <div class=\\\"steps-grid\\\">\\n                    <div class=\\\"step-card animate-on-view\\\">\\n                        <span class=\\\"step-number\\\" aria-hidden=\\\"true\\\">1<\\/span>\\n                        <h3>Raise a Concern<\\/h3>\\n                        <p>Share your Dharma-related concern or initiative with clarity and purpose.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"step-card animate-on-view\\\">\\n                        <span class=\\\"step-number\\\" aria-hidden=\\\"true\\\">2<\\/span>\\n                        <h3>Gather Community Support<\\/h3>\\n                        <p>Build a community of like-minded devotees who stand with you in your cause.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"step-card animate-on-view\\\">\\n                        <span class=\\\"step-number\\\" aria-hidden=\\\"true\\\">3<\\/span>\\n                        <h3>Engage in Discussion<\\/h3>\\n                        <p>Participate in thoughtful discussions to refine your approach and build consensus.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"step-card animate-on-view\\\">\\n                        <span class=\\\"step-number\\\" aria-hidden=\\\"true\\\">4<\\/span>\\n                        <h3>Reach Relevant Authorities<\\/h3>\\n                        <p>Communicate respectfully with temples, Dharmacharyas, and institutions to effect change.<\\/p>\\n                    <\\/div>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n        <!-- ===== Principles ===== -->\\n        <section aria-labelledby=\\\"principles-heading\\\">\\n            <div class=\\\"container\\\">\\n                <div class=\\\"text-center animate-on-view\\\">\\n                    <span class=\\\"hero-badge\\\" style=\\\"background:var(--saffron-light);color:var(--deep-blue);border-color:var(--saffron);display:inline-block;\\\">Core Values<\\/span>\\n                    <h2 id=\\\"principles-heading\\\" class=\\\"section-title\\\">Platform <span class=\\\"highlight\\\">Principles<\\/span><\\/h2>\\n                    <p class=\\\"section-subtitle centered\\\">\\n                        These guiding principles shape every interaction on Sampreshan.\\n                    <\\/p>\\n                <\\/div>\\n                <div class=\\\"principles-grid\\\">\\n                    <div class=\\\"principle-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83e\\udd1d<\\/span>\\n                        <h4>Respectful Dialogue<\\/h4>\\n                        <p>Every conversation is conducted with dignity and mutual respect.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"principle-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\udd0d<\\/span>\\n                        <h4>Authenticity<\\/h4>\\n                        <p>We value truthful representation and genuine concern for Dharma.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"principle-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\udc65<\\/span>\\n                        <h4>Community Participation<\\/h4>\\n                        <p>Collective voices create meaningful change.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"principle-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\udd49\\ufe0f<\\/span>\\n                        <h4>Dharma-Centric Focus<\\/h4>\\n                        <p>All actions are rooted in the eternal principles of Sanatana Dharma.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"principle-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\u262e\\ufe0f<\\/span>\\n                        <h4>Peaceful Engagement<\\/h4>\\n                        <p>We advocate for change through peaceful, lawful, and constructive means.<\\/p>\\n                    <\\/div>\\n                    <div class=\\\"principle-card animate-on-view\\\">\\n                        <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\udccb<\\/span>\\n                        <h4>Transparency<\\/h4>\\n                        <p>Our processes and communications are open and accountable.<\\/p>\\n                    <\\/div>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n        <!-- ===== Allowed \\/ Not Allowed ===== -->\\n        <section class=\\\"bg-light\\\" aria-labelledby=\\\"allowed-heading\\\">\\n            <div class=\\\"container\\\">\\n                <div class=\\\"text-center animate-on-view\\\">\\n                    <span class=\\\"hero-badge\\\" style=\\\"background:var(--saffron-light);color:var(--deep-blue);border-color:var(--saffron);display:inline-block;\\\">Guidelines<\\/span>\\n                    <h2 id=\\\"allowed-heading\\\" class=\\\"section-title\\\">What Can Be <span class=\\\"highlight\\\">Submitted<\\/span><\\/h2>\\n                    <p class=\\\"section-subtitle centered\\\">\\n                        We welcome genuine concerns and proposals that align with the spirit of Sanatana Dharma.\\n                    <\\/p>\\n                <\\/div>\\n                <div class=\\\"two-col-grid\\\">\\n                    <div class=\\\"list-card animate-on-view\\\">\\n                        <h3><span aria-hidden=\\\"true\\\">\\u2705<\\/span> Allowed<\\/h3>\\n                        <ul>\\n                            <li><span class=\\\"check\\\" aria-hidden=\\\"true\\\">\\u2713<\\/span> Temple preservation concerns<\\/li>\\n                            <li><span class=\\\"check\\\" aria-hidden=\\\"true\\\">\\u2713<\\/span> Cultural heritage issues<\\/li>\\n                            <li><span class=\\\"check\\\" aria-hidden=\\\"true\\\">\\u2713<\\/span> Religious education initiatives<\\/li>\\n                            <li><span class=\\\"check\\\" aria-hidden=\\\"true\\\">\\u2713<\\/span> Dharma awareness campaigns<\\/li>\\n                            <li><span class=\\\"check\\\" aria-hidden=\\\"true\\\">\\u2713<\\/span> Community welfare proposals<\\/li>\\n                            <li><span class=\\\"check\\\" aria-hidden=\\\"true\\\">\\u2713<\\/span> Requests to Dharmacharyas<\\/li>\\n                        <\\/ul>\\n                    <\\/div>\\n                    <div class=\\\"list-card not-allowed animate-on-view\\\">\\n                        <h3><span aria-hidden=\\\"true\\\">\\ud83d\\udeab<\\/span> Not Allowed<\\/h3>\\n                        <ul>\\n                            <li><span class=\\\"cross\\\" aria-hidden=\\\"true\\\">\\u2717<\\/span> Hate speech<\\/li>\\n                            <li><span class=\\\"cross\\\" aria-hidden=\\\"true\\\">\\u2717<\\/span> Violence<\\/li>\\n                            <li><span class=\\\"cross\\\" aria-hidden=\\\"true\\\">\\u2717<\\/span> Personal attacks<\\/li>\\n                            <li><span class=\\\"cross\\\" aria-hidden=\\\"true\\\">\\u2717<\\/span> Defamation<\\/li>\\n                            <li><span class=\\\"cross\\\" aria-hidden=\\\"true\\\">\\u2717<\\/span> Illegal activities<\\/li>\\n                            <li><span class=\\\"cross\\\" aria-hidden=\\\"true\\\">\\u2717<\\/span> Unrelated political campaigning<\\/li>\\n                        <\\/ul>\\n                    <\\/div>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n        <!-- ===== ShivBodh Trust ===== -->\\n        <section aria-labelledby=\\\"trust-heading\\\">\\n            <div class=\\\"container\\\">\\n                <div class=\\\"text-center animate-on-view\\\">\\n                    <span class=\\\"hero-badge\\\" style=\\\"background:var(--saffron-light);color:var(--deep-blue);border-color:var(--saffron);display:inline-block;\\\">Inspiration<\\/span>\\n                    <h2 id=\\\"trust-heading\\\" class=\\\"section-title\\\">About <span class=\\\"highlight\\\">ShivBodh Trust<\\/span><\\/h2>\\n                <\\/div>\\n                <div class=\\\"trust-card animate-on-view\\\">\\n                    <span class=\\\"trust-icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\udd31<\\/span>\\n                    <div class=\\\"trust-text\\\">\\n                        <h3>ShivBodh Trust<\\/h3>\\n                        <p>\\n                            ShivBodh Trust is the spiritual beacon behind Sampreshan. Rooted in the\\n                            timeless wisdom of Sanatana Dharma, the Trust is dedicated to the\\n                            preservation of sacred traditions, the promotion of spiritual education,\\n                            and the welfare of the community. Sampreshan extends this mission into\\n                            the digital realm, empowering devotees to participate actively in\\n                            Dharma-related initiatives with respect, integrity, and purpose.\\n                        <\\/p>\\n                    <\\/div>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n        <!-- ===== Contact ===== -->\\n        <section class=\\\"bg-light\\\" aria-labelledby=\\\"contact-heading\\\" id=\\\"contact\\\">\\n            <div class=\\\"container\\\">\\n                <div class=\\\"contact-box animate-on-view\\\">\\n                    <h2 id=\\\"contact-heading\\\">Contact <span style=\\\"color:var(--saffron);\\\">Sampreshan<\\/span><\\/h2>\\n                    <p>\\n                        Have a concern, suggestion, or want to collaborate? Reach out to us \\u2014\\n                        we are here to listen and serve.\\n                    <\\/p>\\n                    <a href=\\\"mailto:sampreshan.tech@gmail.com\\\" class=\\\"email-link\\\" aria-label=\\\"Send an email to Sampreshan\\\">\\n                        <span aria-hidden=\\\"true\\\">\\u2709\\ufe0f<\\/span> sampreshan.tech@gmail.com\\n                    <\\/a>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n    <\\/main>\\n\\n    <!-- ===== Footer ===== -->\\n    <footer class=\\\"site-footer\\\" role=\\\"contentinfo\\\" aria-label=\\\"Site footer\\\">\\n        <div class=\\\"container footer-inner\\\">\\n            <div class=\\\"footer-brand\\\">\\n                <div class=\\\"footer-logo\\\">Sampreshan<span>.<\\/span><\\/div>\\n                <div class=\\\"footer-tagline\\\">Vasudhaiva Kutumbakam<\\/div>\\n            <\\/div>\\n            <div class=\\\"footer-copy\\\">\\n                &copy; <span class=\\\"year\\\" id=\\\"year\\\"><\\/span> Sampreshan. All rights reserved.\\n            <\\/div>\\n        <\\/div>\\n    <\\/footer>\\n\\n    <!-- ===== JavaScript ===== -->\\n    <script>\\n        (function() {\\n            \'use strict\';\\n\\n            \\/\\/ ---- Auto-update copyright year ----\\n            document.getElementById(\'year\').textContent = new Date().getFullYear();\\n\\n            \\/\\/ ---- Mobile nav toggle ----\\n            const toggle = document.getElementById(\'navToggle\');\\n            const navLinks = document.getElementById(\'navLinks\');\\n\\n            if (toggle && navLinks) {\\n                toggle.addEventListener(\'click\', function() {\\n                    const expanded = this.getAttribute(\'aria-expanded\') === \'true\' ? false : true;\\n                    this.setAttribute(\'aria-expanded\', expanded);\\n                    navLinks.classList.toggle(\'open\');\\n                });\\n\\n                \\/\\/ Close nav on link click (mobile)\\n                navLinks.querySelectorAll(\'a\').forEach(function(link) {\\n                    link.addEventListener(\'click\', function() {\\n                        toggle.setAttribute(\'aria-expanded\', \'false\');\\n                        navLinks.classList.remove(\'open\');\\n                    });\\n                });\\n            }\\n\\n            \\/\\/ ---- Intersection Observer for scroll animations ----\\n            const animateElements = document.querySelectorAll(\'.animate-on-view\');\\n\\n            if (\'IntersectionObserver\' in window) {\\n                const observer = new IntersectionObserver(function(entries) {\\n                    entries.forEach(function(entry) {\\n                        if (entry.isIntersecting) {\\n                            entry.target.classList.add(\'visible\');\\n                            \\/\\/ Optionally unobserve after animation\\n                            observer.unobserve(entry.target);\\n                        }\\n                    });\\n                }, {\\n                    threshold: 0.15,\\n                    rootMargin: \'0px 0px -40px 0px\'\\n                });\\n\\n                animateElements.forEach(function(el) {\\n                    observer.observe(el);\\n                });\\n            } else {\\n                \\/\\/ Fallback: show all elements immediately\\n                animateElements.forEach(function(el) {\\n                    el.classList.add(\'visible\');\\n                });\\n            }\\n\\n            \\/\\/ ---- Smooth anchor scroll (progressive enhancement) ----\\n            document.querySelectorAll(\'a[href^=\\\"#\\\"]\').forEach(function(anchor) {\\n                anchor.addEventListener(\'click\', function(e) {\\n                    const targetId = this.getAttribute(\'href\');\\n                    if (targetId === \'#\') return;\\n                    const target = document.querySelector(targetId);\\n                    if (target) {\\n                        e.preventDefault();\\n                        const headerOffset = 80;\\n                        const elementPosition = target.getBoundingClientRect().top;\\n                        const offsetPosition = elementPosition + window.pageYOffset - headerOffset;\\n                        window.scrollTo({\\n                            top: offsetPosition,\\n                            behavior: \'smooth\'\\n                        });\\n                        \\/\\/ Update URL hash without triggering scroll\\n                        history.pushState(null, null, targetId);\\n                    }\\n                });\\n            });\\n\\n        })();\\n    <\\/script>\\n\\n<\\/body>\\n<\\/html>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false,\"styles\":{\"e-7cecf89\":{\"id\":\"e-7cecf89\",\"label\":\"local\",\"type\":\"class\",\"variants\":[{\"meta\":{\"breakpoint\":\"desktop\",\"state\":null},\"props\":{\"flex-direction\":{\"$$type\":\"string\",\"value\":\"column\"}},\"custom_css\":null}]}},\"interactions\":[],\"editor_settings\":[],\"version\":\"0.0\"}]'),
